import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"RFC 0090 — Default privacy policy and terms of service, platform and plugin","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0090-default-privacy-policy-and-tos.md"},"headers":[],"relativePath":"rfcs/0090-default-privacy-policy-and-tos.md","filePath":"rfcs/0090-default-privacy-policy-and-tos.md"}'),i={name:"rfcs/0090-default-privacy-policy-and-tos.md"};function r(n,e,s,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="rfc-0090-—-default-privacy-policy-and-terms-of-service-platform-and-plugin" tabindex="-1">RFC 0090 — Default privacy policy and terms of service, platform and plugin <a class="header-anchor" href="#rfc-0090-—-default-privacy-policy-and-terms-of-service-platform-and-plugin" aria-label="Permalink to &quot;RFC 0090 — Default privacy policy and terms of service, platform and plugin&quot;">​</a></h1><p><strong>Status:</strong> Draft<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> Claude Code<br><strong>Scope:</strong> repo root (<code>PRIVACY.md</code>, <code>TOS.md</code>), <code>runtime</code> (<code>/privacy</code>, <code>/tos</code>, middleware), <code>docs/legal/</code>, <code>docs/self-hosting.md</code>, <code>docs/plugin-development.md</code>, <code>scripts/generate-registry.ts</code>, <code>packages/manifest</code>, <code>registry/</code>; a companion follow-up (not designed here) in the separate <code>sovereign-infra</code> repo.<br><strong>Incorporated into plan:</strong> No — documentation-first.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Every Sovereign instance serves <code>/privacy</code> and <code>/tos</code> from day one, no operator action required, rendered from plain root-level <code>PRIVACY.md</code> and <code>TOS.md</code> files shipped with the platform. An operator who wants their own name and contact on the page replaces those two files — in their fork, or via a mount in their <code>sovereign-infra</code> deployment — with a filled-in copy of a template kept in <code>docs/legal/</code>. The only difference between the shipped default and the operator&#39;s copy is the operator&#39;s name and contact; nothing else changes. The same pattern repeats one level down: every plugin ships its own root-level <code>PRIVACY.md</code>/<code>TOS.md</code>, auto-served at <code>&lt;routePrefix&gt;/privacy</code> and <code>&lt;routePrefix&gt;/tos</code> by the same build step that already composes every other plugin route, and a plugin can&#39;t be published to the registry without them.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p><a href="./../research/0007-operator-compliance-surface.html">Research 0007</a> found <code>instance_config</code> carries branding but nothing legal, and rejected shipping project-authored policy text that makes claims about a specific operator&#39;s identity or jurisdiction nobody confirmed (&quot;Option C&quot; — see that doc). This RFC doesn&#39;t do that: the root <code>PRIVACY.md</code>/<code>TOS.md</code> state only what&#39;s true of the Sovereign platform software itself, for any instance, unconditionally — no operator name, no jurisdiction, no guessed fact. An operator who wants to add their own identity does so explicitly, by replacing the file with their own copy. Nothing is asserted on an operator&#39;s behalf without them having written it.</p><p>Plugins are the same problem one level down and were previously undocumented: a plugin can request device capabilities, send mail, or process data the platform has no visibility into, and there has been no place — for an admin reviewing it before install, or a user of it — to find out what it does with data.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li>No <code>PRIVACY.md</code>/<code>TOS.md</code> exists at the repo root today.</li><li><code>runtime/app/privacy/page.tsx</code> and <code>runtime/app/terms/page.tsx</code> (built earlier this session) are static, hand-written pages with <code>[BRACKETED]</code> operator-identity placeholders rendered verbatim — superseded by this RFC. <code>runtime/middleware.ts:602</code> already excludes both routes from the auth gate; the exclusion is reused, only content sourcing changes (and <code>/terms</code> renames to <code>/tos</code>).</li><li><code>docs/legal/operator-template-privacy.md</code> and <code>-terms.md</code> (also built this session) are far more heavily parameterized than needed — placeholders for jurisdiction, SMTP provider, retention policy, children&#39;s policy, acceptable-use specifics. This RFC trims them down to match the root default plus only a name/contact field, per the simpler design below.</li><li><code>scripts/generate-registry.ts</code>&#39;s <code>composePlugins()</code> (<code>:455-491</code>) already copies (dev: incremental <code>syncDir</code>; prod: <code>symlinkSync</code>) each plugin&#39;s <code>app/</code> tree into its routed destination — <code>composeTargets(manifest)</code> resolves the destination(s) from the manifest&#39;s <code>routePrefix</code>. This runs for every plugin, every <code>pnpm generate</code>/<code>pnpm dev</code>/build, and is the existing mechanism this RFC extends — not new infrastructure. Each plugin&#39;s own directory (<code>plugins/&lt;dir&gt;/</code>, or the equivalent for an externally-hosted registry plugin) is a sibling of its <code>app/</code> folder, so a root-level <code>PRIVACY.md</code>/<code>TOS.md</code> there is visible to this same step.</li><li><code>packages/manifest/src/validate.ts</code> has <code>validateManifest(input: unknown)</code> and <code>validateRegistryEntry(input: unknown)</code> (<code>:20</code>, <code>:37</code>) — both pure functions over the manifest/registry-entry JSON, no filesystem access. They cannot check for a sibling file&#39;s existence directly; the actual enforcement points with filesystem access are <code>composePlugins()</code> itself (build time, every install) and <code>scripts/generate-registry.ts</code>&#39;s registry-submission validation path (<code>registry:validate</code>/<code>registry:check</code> — already the human-reviewed gate for the public registry).</li><li>No markdown-rendering dependency exists anywhere in the repo today (no <code>react-markdown</code>, <code>remark</code>, <code>marked</code>, or <code>markdown-to-jsx</code> in any <code>package.json</code>). This RFC needs one, added once to <code>runtime</code>.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="platform-default-root-privacy-md-tos-md" tabindex="-1">Platform default: root <code>PRIVACY.md</code> / <code>TOS.md</code> <a class="header-anchor" href="#platform-default-root-privacy-md-tos-md" aria-label="Permalink to &quot;Platform default: root `PRIVACY.md` / `TOS.md`&quot;">​</a></h3><p>Two new files at the repo root, sibling to <code>LICENSE</code> and <code>README.md</code>. Content: what the platform software does, unconditionally true for any instance — account fields collected at registration, cookies, PWA caching behavior, how outbound email works, where data is stored, how push works, data export/deletion. No operator name, no jurisdiction, no guessed fact. This is a rewrite of the useful parts of <code>docs/legal/operator-template- privacy.md</code>/<code>-terms.md</code> as already researched this session, with every operator-identity placeholder removed rather than left as a bracket.</p><p><code>runtime/app/privacy/page.tsx</code> and the renamed <code>runtime/app/tos/page.tsx</code> read and render these two files directly (markdown → React, via a small shared renderer added to <code>runtime</code>) — a plain file read, no database, no computed facts, no redirect logic. <code>LegalLinks</code> (<code>packages/ui</code>), the middleware exclusion (<code>runtime/middleware.ts:602</code>, <code>terms</code> → <code>tos</code>), and the Account plugin footer link (<code>plugins/account/app/layout.tsx</code>) are otherwise unaffected.</p><h3 id="operator-override-replace-the-file" tabindex="-1">Operator override: replace the file <a class="header-anchor" href="#operator-override-replace-the-file" aria-label="Permalink to &quot;Operator override: replace the file&quot;">​</a></h3><p>An operator who wants their name and contact on the page copies <code>docs/legal/operator-template-privacy.md</code>/<code>-terms.md</code> — the same content as the root default, plus an &quot;operated by [Name], contact [Email]&quot; line — fills in the two blanks, and replaces <code>PRIVACY.md</code>/<code>TOS.md</code> with it:</p><ul><li><strong>Fork-and-track operators:</strong> edit the file directly in their fork and commit it, the same file the platform ships (not a separate <code>operator/</code> path — the point is that only the two identity fields differ, so there&#39;s nothing else to keep merge-conflict-isolated the way <code>operator/OPERATOR.md</code> needs to be).</li><li><strong><code>sovereign-infra</code>-deployed operators:</strong> mount their filled-in copy over the shipped file&#39;s path in their <code>docker-compose.override.yml</code> (<code>operator/docker-compose.override.yml</code> is already a documented optional file per RFC 0028) — a one-line volume mount, no runtime code change. <code>sovereign-infra</code> is a separate repo; this RFC only notes the integration point and that its own deployment template should carry a copy of the operator template as a starting point — a companion change there, not part of this monorepo&#39;s adoption path.</li></ul><p><code>docs/self-hosting.md</code> gets a short section under both the fork-and-track and Docker-only setup tracks pointing at this template and the two-field difference, so an operator finds it without reading this RFC.</p><h3 id="plugin-default-root-privacy-md-tos-md-per-plugin-auto-served" tabindex="-1">Plugin default: root <code>PRIVACY.md</code> / <code>TOS.md</code> per plugin, auto-served <a class="header-anchor" href="#plugin-default-root-privacy-md-tos-md-per-plugin-auto-served" aria-label="Permalink to &quot;Plugin default: root `PRIVACY.md` / `TOS.md` per plugin, auto-served&quot;">​</a></h3><p>Every plugin — first-party (<code>plugins/*</code>), example (<code>example-plugins/*</code>), or external (registry, <code>.local</code>) — ships its own <code>PRIVACY.md</code>/<code>TOS.md</code> at the root of its own directory, sibling to <code>manifest.json</code> and <code>app/</code> (not inside <code>app/</code>, so it isn&#39;t confused with the plugin&#39;s own page routes).</p><p><code>composePlugins()</code> (<code>scripts/generate-registry.ts:455</code>) gains one small addition to its existing per-plugin loop: for each <code>dest</code> in <code>composeTargets(manifest)</code>, after <code>linkOrCopyTarget</code> composes the plugin&#39;s <code>app/</code> tree as it already does, write two small generated page files — <code>dest/privacy/page.tsx</code> and <code>dest/tos/page.tsx</code> — that import and render that plugin&#39;s root <code>PRIVACY.md</code>/<code>TOS.md</code> through the same shared markdown renderer the platform-level pages use. This makes <code>&lt;routePrefix&gt;/privacy</code> and <code>&lt;routePrefix&gt;/tos</code> real, auto-served routes for every composed plugin, with no plugin-author code beyond the two markdown files. If a plugin is missing one (only possible for a <code>.local</code>/unregistered plugin — see Enforcement), the generated route renders a plain &quot;this app has not published this page&quot; state rather than a broken link.</p><p><code>docs/legal/plugin-template-privacy.md</code> and <code>plugin-template-terms.md</code> (new) give plugin authors a starting draft — same shape as the operator template, scoped to what a typical plugin might collect (its own tables, any external API calls it makes, any device capability it requests) — copied into a new plugin&#39;s root and edited to match what that specific plugin actually does. <code>packages/create-plugin</code>&#39;s scaffolder and <code>sovereign-plugin-template</code> should include these two files pre-populated from the template so a newly scaffolded plugin has them from the start rather than needing to remember to add them.</p><h3 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h3><p>Split by where filesystem access actually exists (see Current state — pure manifest validation can&#39;t check for a sibling file):</p><ul><li><strong><code>composePlugins()</code>, every build:</strong> a plugin missing <code>PRIVACY.md</code> or <code>TOS.md</code> at its root logs a clear warning (not a hard failure — would otherwise break every existing local/<code>.local</code> dev plugin the moment this ships) naming the plugin and the missing file.</li><li><strong><code>registry:validate</code>/<code>registry:check</code>, registry submission:</strong> hard requirement. A plugin can&#39;t be added to <code>registry/plugins.json</code> without both files present in its repo at the declared ref — this is the one point that already does human review, so it&#39;s the right place for a real gate rather than a warning.</li></ul><p><code>docs/plugin-development.md</code> gets a new &quot;Privacy and Terms of Service&quot; section next to the manifest reference: what the two files are, where they live, the auto-served routes, a link to the two templates, and the registry-submission requirement.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><p><strong>A database-backed, per-instance config surface with Console-editable identity fields, redirects, and computed-fact interpolation</strong> (this RFC&#39;s own previous draft). Replaced — real overkill for what&#39;s actually needed. A flat file the operator replaces achieves the same outcome (an operator&#39;s name showing up on the page) with no schema migration, no settings form, no redirect logic, and no build-time interpolation engine to maintain.</p><p><strong>Generic runtime-synthesized <code>&lt;routePrefix&gt;/privacy</code> route driven by a manifest field (<code>privacyUrl</code>) instead of a convention-based file.</strong> Rejected — a fixed file-at-plugin-root convention needs no new manifest field, no URL validation, and no distinction between &quot;a page under the plugin&#39;s own <code>app/</code> tree&quot; and &quot;an external link&quot;; every plugin gets the exact same predictable route with zero configuration.</p><p><strong>Auto-serve operator-identity placeholder text with no operator action</strong> (this session&#39;s first approach — <code>[Operator Name]</code> brackets rendered verbatim). Rejected — asserts something about a specific operator nobody confirmed. Distinct from the chosen design, which asserts nothing beyond what&#39;s true of the platform software itself until an operator explicitly replaces the file.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li>Exact markdown-rendering dependency for <code>runtime</code> (<code>react-markdown</code> vs. <code>markdown-to-jsx</code> vs. hand-rolled) — an implementation detail, needs a <code>pnpm-workspace.yaml</code> catalog entry once chosen.</li><li>Whether the <code>composePlugins()</code> warning (missing files, non-registry plugins) should eventually become a hard failure once the ecosystem has had time to adopt this — not decided now; revisit once registry adoption data exists.</li><li>Exact starting content for <code>docs/legal/plugin-template-privacy.md</code>/ <code>-terms.md</code> — needs a pass similar to the one already done for the operator template&#39;s account/cookie/PWA/email/push inventory, scoped to what&#39;s generically true of <em>any</em> plugin (its own DB tables under the platform&#39;s data model) versus what&#39;s plugin-specific and has to stay a blank.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Documentation-first; no scheduling commitment yet. When scheduled:</p><ol><li>Write root <code>PRIVACY.md</code>/<code>TOS.md</code>.</li><li>Rewrite <code>docs/legal/operator-template-privacy.md</code>/<code>-terms.md</code> down to &quot;root default plus name/contact&quot; per the simplified design.</li><li>Add the markdown-rendering dependency to <code>runtime</code>; rework <code>runtime/app/privacy/page.tsx</code> and rename <code>runtime/app/terms/</code> → <code>runtime/app/tos/</code> (update <code>runtime/middleware.ts:602</code>&#39;s matcher and every <code>LegalLinks</code> <code>termsHref</code> usage this session added) to read the root files.</li><li>Write <code>docs/legal/plugin-template-privacy.md</code>/<code>plugin-template-terms.md</code>.</li><li>Add <code>PRIVACY.md</code>/<code>TOS.md</code> to every first-party plugin (<code>plugins/console</code>, <code>plugins/launcher</code>, <code>plugins/account</code>, <code>plugins/tasks</code>) and <code>example-plugins/*</code> so nothing breaks when enforcement ships.</li><li>Extend <code>composePlugins()</code> to generate <code>privacy/page.tsx</code>/<code>tos/page.tsx</code> per composed plugin route, plus the missing-file warning.</li><li><code>docs/plugin-development.md</code>&#39;s new section; <code>packages/create-plugin</code> scaffolder update.</li><li><code>registry:validate</code>/<code>registry:check</code> hard requirement.</li><li><code>docs/self-hosting.md</code> sections for both operator tracks.</li><li>Companion follow-up (separate repo, tracked here for visibility only): <code>sovereign-infra</code> gets the operator template pre-populated in its own deployment scaffold.</li></ol><p>No published-package semver impact beyond a routine <code>@sovereignfs/create- plugin</code> scaffolder update and a minor <code>@sovereignfs/ui</code> <code>LegalLinks</code> prop rename (<code>termsHref</code> usages) on the <code>/tos</code> rename.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>August 2026</td><td>Simplified: flat-file default + override, per-plugin auto-served routes via existing <code>composePlugins()</code>, dropped <code>instance_config</code>/Console/computed-facts design</td></tr></tbody></table>',38)])])}const u=o(i,[["render",r]]);export{m as __pageData,u as default};
